const item = $input.first().json;
const body = item.body || item;
const courseQuery = (body.courseQuery || '').toString().trim();
const examType = body.examType === 'final' ? 'final' : 'vize';
if (courseQuery.length < 2) {
  return [{ json: { invalid: true, courseQuery, examType, error: { success: false, error: { code: 'INVALID_INPUT', stage: 'input_validation', message: 'Ders adı/kodu geçersiz (en az 2 karakter).' } } } }];
}
const examTr = examType === 'final' ? 'FİNAL (dönemin tamamı)' : 'VİZE (dönemin ilk yarısı)';
const prompt = 'Manisa Celal Bayar Üniversitesi öğrencisi için sınav hazırlık asistanısın. Ders: "' + courseQuery + '". Sınav: ' + examTr + '. Bu dersin tipik müfredatını (syllabus) dikkate alarak bu sınavda çıkması beklenen ana konuları belirle. Her konu için: kısa bir Türkçe açıklama, önem derecesi (yüksek/orta/düşük) ve 1-3 adet YouTube eğitim videosu öner. Videolar için GERÇEK video kimliği UYDURMA; bunun yerine Türkçe bir YouTube arama sorgusu (searchQuery) ver. Tüm metinler Türkçe olsun.';
const geminiBody = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.4, responseMimeType: 'application/json', responseSchema: { type: 'OBJECT', properties: { course: { type: 'OBJECT', properties: { code: { type: 'STRING' }, name: { type: 'STRING' } } }, topics: { type: 'ARRAY', items: { type: 'OBJECT', properties: { title: { type: 'STRING' }, description: { type: 'STRING' }, importance: { type: 'STRING' }, videos: { type: 'ARRAY', items: { type: 'OBJECT', properties: { title: { type: 'STRING' }, channel: { type: 'STRING' }, searchQuery: { type: 'STRING' } } } } } } } } } } };
return [{ json: { invalid: false, courseQuery, examType, geminiBody } }];

const g = $input.first().json;
const ctx = $('Hazırla & Doğrula').first().json;
const examType = ctx.examType || 'vize';
const courseQuery = ctx.courseQuery || '';
function errOut(code, stage, message) {
  return [{ json: { response: { success: false, error: { code, stage, message } } } }];
}
if (g && g.error) {
  const m = (g.error && (g.error.message || g.error.reason)) || JSON.stringify(g.error);
  return errOut('GEMINI_ERROR', 'gemini_generation', 'Gemini çağrısı başarısız: ' + m);
}
let parsed;
try {
  const text = g && g.candidates && g.candidates[0] && g.candidates[0].content && g.candidates[0].content.parts && g.candidates[0].content.parts[0] && g.candidates[0].content.parts[0].text;
  if (!text) throw new Error('Gemini boş yanıt döndürdü.');
  parsed = typeof text === 'string' ? JSON.parse(text) : text;
} catch (e) {
  return errOut('SCHEMA_INVALID', 'response_format', 'Gemini yanıtı çözümlenemedi: ' + e.message);
}
const topics = Array.isArray(parsed.topics) ? parsed.topics : [];
if (!topics.length) {
  return errOut('SYLLABUS_NOT_FOUND', 'syllabus_fetch', 'Bu ders için konu üretilemedi.');
}
const response = { success: true, source: 'n8n', course: parsed.course || { code: '', name: courseQuery }, examType, topics, meta: { model: 'gemini-2.0-flash', generatedAt: new Date().toISOString() } };
return [{ json: { response } }];
